791	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
792	    //    2D weights (INTEGRATION-OPTSTAGES §3). IDENTICAL to the vit twin
793	    //    (fused_vit_megakernel.cuh P2.7) — same shared opt_stages_precompute.cuh
794	    //    helpers, same barrier sequence — only the per-model 2D table (dectc::
795	    //    kDecMuon2D, 11 matrices including tok[99,128]/pos[4,128]) and offset array
796	    //    (kDecOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
797	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
798	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X
799	    //    → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step
800	    //    apply (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (biases, LN γ/β)
801	    //    take the AdamW aux tail in P3. The elementwise bodies CALL muon.h
802	    //    (muon_momentum_normalize_step via the phaseA buf body, muon_ns_combine_step,
803	    //    muon_update_step); the matmuls are the cited new device code (the eager path
804	    //    delegates to torch::mm/cuBLAS). Guarded so every other opt is byte-identical
805	    //    (no extra barriers / work).
806	    if constexpr (Opt == OptId::Muon) {
807	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
808	        PrecomputeWorkspace pw{};
809	        pw.muon_X            = muon_base;
810	        pw.muon_AX           = pw.muon_X   + dectc::kDecMuonMaxNumel;
811	        pw.muon_AAX          = pw.muon_AX  + dectc::kDecMuonMaxNumel;
812	        pw.muon_orth         = pw.muon_AAX + dectc::kDecMuonMaxNumel;
813	        pw.muon_A            = pw.muon_orth + dectc::kDecMuonMaxNumel;
814	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows;
815	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
816	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
817	        const int   ns_steps = 5;                 // bindings.cpp default
818	        for (int mi = 0; mi < dectc::kDecNumMuon2D; ++mi) {
819	            const dectc::DecMuon2D M = dectc::kDecMuon2D[mi];
820	            const int rows = M.rows, cols = M.cols;
821	            const int64_t numel = (int64_t)rows * cols;
822	            const int64_t off   = (int64_t)kDecOffsets[M.tidx];
823	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
824	            pw.muon_buf = st.exp_avg + off;
825	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
826	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
827	            bar.sync();
828	            muon_norm_reduce_phaseB(ctx, pw);
829	            bar.sync();
830	            muon_scale_X(numel, pw);
831	            bar.sync();
832	            // NS iterations. After each combine, orth holds the new iterate; swap so
833	            // the next iteration reads it as X. ns_steps swaps → final result is in
834	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
835	            for (int s = 0; s < ns_steps; ++s) {
836	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
837	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
838	                bar.sync();
839	                // AX = A X   (M=rows,N=cols,K=rows).
840	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
841	                bar.sync();
842	                // AAX = A (AX) (M=rows,N=cols,K=rows).
843	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
844	                bar.sync();
845	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
846	                bar.sync();
847	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
848	            }
849	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
850	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
851	            const float neg_lr_scale = -lr * scale;
852	            const float decay_factor = 1.0f - lr * st.wd;
853	            float* __restrict__ p = params + off;
854	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
855	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
856	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
857	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
858	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
859	        }
860	    }
