862	    // ── P2.45 (SuperGrok11/15 ONLY) staged into P3: the per-TENSOR meta-net mu
863	    //    precompute (INTEGRATION-OPTSTAGES §4/§5). SINGLE task-queue drain, NO grid
864	    //    barrier: each tensor T is SELF-CONTAINED — mu(T) = sg_rescale·phi(g[T],
865	    //    sharpness[T]) (per element) and, for SG11, the per-tensor cosine gate(T) =
866	    //    clamp(cos(g[T], mu[T]), 0, 1) depend ONLY on T's own elements (never on any
867	    //    other tensor's mu), so mu(+gate)→apply fuse into ONE body the SAME CTA owns
868	    //    end-to-end inside the EXISTING P3 drain (every thread of a CTA claims the same
869	    //    tensor t via the block-level task_slot, so the helper's __syncthreads/block-
870	    //    reduce are block-uniform and safe). NOT a separate full-queue mu pre-pass +
871	    //    a second apply drain (that would silently no-op — see the SG11 block in
872	    //    opt_stages_precompute.cuh). The phi weights (per-TENSOR weight set) are staged
873	    //    to SMEM ONCE per block before the drain. SG15's gate is the host scalar st.gate
874	    //    (no cosine stage); SG11 binds the per-tensor gate the helper returns. sharpness
875	    //    (the 2nd MLP input) was produced by P2.4 (or the cached prior step).
876	    __shared__ float sg_sW1[kSgPhiHidden * 2];
877	    __shared__ float sg_sb1[kSgPhiHidden];
878	    __shared__ float sg_sW2[kSgPhiHidden];
879	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
880	        sg_stage_phi_weights<kSgPhiHidden>(st.sg_phi_W1, st.sg_phi_b1, st.sg_phi_W2,
881	                                           sg_sW1, sg_sb1, sg_sW2);   // syncs
882	    }
883	
884	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
885	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
886	    st.lr = lr;
887	    {
888	        __shared__ int task_slot;
889	        TaskQueue q = ctx.queue();
890	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
891	             t = q.next_block(&task_slot)) {
892	            const int n = kDecSizes[t];
893	            const int64_t off = (int64_t)kDecOffsets[t];
894	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
895	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
896	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
897	            if constexpr (Opt == OptId::Muon) {
898	                if (dectc::dec_is_muon_2d(t)) continue;
899	            }
900	            FusedOptState ts = rebase_state<Opt>(st, off);
901	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
902	            //     t == the tensor's flat named_parameters() layer index (the
903	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
904	            //     enumeration order, so t IS the eager layer index). bc1 must be
905	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
906	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
907	            if constexpr (Opt == OptId::GrokAdamW) {
908	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
909	                ts.beta1 = b1;
910	                ts.bc1   = 1.0f - powf(b1, (float)step);
911	            }
912	            // SuperGrok11/15 meta-net mu (+ SG11 per-tensor gate) precompute for THIS
913	            // tensor, BEFORE the apply reads ts.mu/ts.gate. mu(T)=sg_rescale·phi(g,
914	            // sharpness) over [off,off+n); SG11 also computes the clamped cosine gate(T)
915	            // (block-uniform __syncthreads/reduce — the whole CTA owns t). SG15's gate is
916	            // st.gate (host sigmoid(accuracy)). Helpers index grad/sharpness/mu by off+i,
917	            // so pass the BASE pointers (st.mu, grad, st.sharpness) + off; the apply then
918	            // reads ts.mu (== st.mu+off). phi_b2 read on-device from sg_phi_W2[H].
919	            if constexpr (Opt == OptId::SuperGrok11) {
920	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
921	                                                           : st.sg_phi_b2;
922	                const float g8 = sg11_precompute_mu_and_gate_for_tensor<kSgPhiHidden>(
923	                    st.mu, grad, st.sharpness, sg_sW1, sg_sb1, sg_sW2,
924	                    b2, st.sg_rescale, off, n);
