909	    // CTAs co-reside per SM. Launch occ·n_sms CTAs (one full residency set) so the
910	    // co-resident CTAs hide each other's HBM latency across the scan/conv/LN phases
911	    // that run fully exposed at occ=1 — the persistent grid barrier rendezvous is
912	    // over the LAUNCHED count and occ·n_sms are guaranteed simultaneously resident,
913	    // so it stays hang-free. Determinism is per fixed launched nCTA (ascending-CTA
914	    // reduce). At min-blocks==1 (shipped default) occ==1 → identical to before.
915	    unsigned waves = (SG_MBTC_MIN_BLOCKS_PER_SM >= 2 && occ > 1) ? (unsigned)occ : 1u;
916	    unsigned launch_ctas = (unsigned)n_sms * waves;
917	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
